using Xunit.Abstractions;
using EnderOverhaul.EnderDynamics.Minecraft.Entities;
using EnderOverhaul.EnderDynamics.Utils.Vector;


namespace EnderOverhaul.EnderDynamics.Test.Minecraft;

public class EnderPearlEntityTest(ITestOutputHelper testOutputHelper)
{
    [Theory , MemberData(nameof(TestData_TestEnderPearlTicking))]
    public void TestEnderPearlTicking(EnderPearlEntity enderPearl , EnderPearlEntity expected , int tickCount)
    {
        for (int i = 0; i < tickCount; i++)
            enderPearl.Tick();

        testOutputHelper.WriteLine($"Tick {tickCount}");
        testOutputHelper.WriteLine(
                $"Position:\n"
              + $"\tactual: ({enderPearl.Position.X}, {enderPearl.Position.Y}, {enderPearl.Position.Z})\n"
              + $"\texpect: ({expected.Position.X}, {expected.Position.Y}, {expected.Position.Z})"
            );
        testOutputHelper.WriteLine(
                $"Position:\n"
              + $"\tactual: ({enderPearl.Motion.X}, {enderPearl.Motion.Y}, {enderPearl.Motion.Z})\n"
              + $"\texpect: ({expected.Motion.X}, {expected.Motion.Y}, {expected.Motion.Z})"
            );

        Assert.Equal(expected.Position , enderPearl.Position);
        Assert.Equal(expected.Motion , enderPearl.Motion);
    }
